-- changeset SantiGodoy:create_province_table_01 
CREATE TABLE IF NOT EXISTS public.province (
    id BIGSERIAL PRIMARY KEY,
    name VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITHOUT TIME ZONE,
    deleted_at TIMESTAMP WITHOUT TIME ZONE,
    deleted_by VARCHAR(255)
);
COMMENT ON TABLE public.province IS 'Almacena las provincias.';
COMMENT ON COLUMN public.province.name IS 'Nombre único de la provincia.';

-- changeset SantiGodoy:create_city_table_01 
CREATE TABLE IF NOT EXISTS public.city (
    id BIGSERIAL PRIMARY KEY,
    zip_code VARCHAR(50) NOT NULL, 
    name VARCHAR(100) NOT NULL,
    province_id BIGINT NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITHOUT TIME ZONE,
    deleted_at TIMESTAMP WITHOUT TIME ZONE,
    deleted_by VARCHAR(255),

    CONSTRAINT fk_city_province FOREIGN KEY (province_id) REFERENCES public.province(id),
    CONSTRAINT uq_city_name_province UNIQUE (name, province_id)
);
COMMENT ON TABLE public.city IS 'Almacena las ciudades y su provincia asociada.';
COMMENT ON COLUMN public.city.name IS 'Nombre de la ciudad.';
COMMENT ON COLUMN public.city.province_id IS 'ID de la provincia a la que pertenece la ciudad.';


